on_save_model_field:
if (!empty([[[field]]]) && is_string([[[field]]]))
{
	$ticketGuid = $data['guid'] ?? 'error';

	// Retrieve existing language records for this company
	$existing = Super___9d76b8dc_3883_4755_b11c_131d19ca8a53___Power::_('Data.Items')
		->table('ticket_comment')
		->get([$ticketGuid], 'ticket');

	$i = 0;
	$ticketSub["ticket{$i}"] = [
		'guid' => '',
		'comment' => [[[field]]]
	];

	// Index existing records by language for quick lookup
	if (!empty($existing))
	{
		foreach ($existing as $row)
		{
			if (!empty($row->ticket))
			{
				$i++;
				$ticketSub["ticket{$i}"] =  [
					'guid' => $row->guid,
					'comment' => $row->comment
				];
			}
		}
	}

	Super___9d76b8dc_3883_4755_b11c_131d19ca8a53___Power::_('Data.Subform')
		->table('ticket_comment')
		->set($ticketSub, 'guid', 'ticket', $ticketGuid);
	unset([[[field]]]);
}
